<template><component :is="as" class="sf-card" :class="['sf-card--'+tone,{'sf-card--compact':compact}]"><header v-if="title||$slots.header" class="sf-card__header"><slot name="header"><h3>{{ title }}</h3></slot><slot name="accessory"/></header><slot/><footer v-if="$slots.footer" class="sf-card__footer"><slot name="footer"/></footer></component></template>
<script>export default {name:'SfCard',props:{as:{type:String,default:'section'},title:String,compact:Boolean,tone:{type:String,default:'default',validator:v=>['default','membership','subtle','commerce'].includes(v)}}}</script>
